    { order: 'C2', dedupKey: 'k2' }, // duplicate of index 3
  ]);
  assert.equal(acks.length, 5);
  assert.deepEqual(acks[2], acks[0]);
  assert.deepEqual(acks[4], acks[3]);
  assert.deepEqual(
    acks.map((a) => a.seq),
    [1, 2, 1, 3, 3],
  );
  assert.equal(bus.stats().published, 3);
  assert.equal(bus.stats().seq, 3);
