      bytes: Buffer.byteLength(JSON.stringify({ i }), 'utf8'),
      record: { i },
    }) + '\n';
  writeFileSync(path.join(dir, 'bus.0000000001.jsonl'), [1, 2, 3].map(line).join(''));
