  const marker = {
    t: 't',
    gen: 0,
    horizon: 3,
    seq: 5,
    bytes,
    published: 5,
    replayed: 0,
    positions: { c: 3 },
    dedup: [['k1', { id: 'id-1', seq: 1 }]],
  };
  writeFileSync(path.join(dir, 'bus.jsonl'), JSON.stringify(marker) + '\n');

