for (let round = 0; round < 40; round++) {
  const dir = `/tmp/fuzz-bus-${round}`;
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  let bus = createBus({ path: dir, fsync: round % 2 === 0 });
  const firstAck = new Map(); // dedupKey -> ack
  let expectedPublished = 0;
  let maxSeq = 0;
  let lastStats = { seq: 0, bytes: 0, published: 0, replayed: 0 };

  const check = async () => {
    const got = await bus.replay(0);
    // contiguous suffix ending at maxSeq
    for (let k = 0; k < got.length; k++) assert.equal(got[k].seq, got[0].seq + k, `gap at round ${round}`);
    if (got.length) assert.equal(got[got.length - 1].seq, maxSeq, 'suffix must end at maxSeq');
    const s = bus.stats();
    assert.equal(s.seq, maxSeq);
    assert.equal(s.published, expectedPublished);
    assert.ok(s.bytes >= lastStats.bytes && s.published >= lastStats.published, 'stats shrank');
    lastStats = s;
  };

  for (let step = 0; step < 60; step++) {
    const r = rand();
    if (r < 0.35) {
      const useKey = rand() < 0.4;
      const key = useKey ? `k${Math.floor(rand() * 5)}` : undefined;
      const rec = { v: Math.floor(rand() * 1000) };
      if (key) rec.dedupKey = key;
      const ack = await bus.publish(rec);
      if (key && firstAck.has(key)) {
        assert.deepEqual(ack, firstAck.get(key), 'dedup ack changed');
      } else {
        maxSeq += 1; expectedPublished += 1;
        assert.equal(ack.seq, maxSeq);
        if (key) firstAck.set(key, ack);
      }
    } else if (r < 0.45) {
      const n = 1 + Math.floor(rand() * 4);
      const recs = Array.from({ length: n }, () => ({ v: Math.floor(rand() * 1000) }));
      const acks = await bus.publishBatch(recs);
      for (const a of acks) { maxSeq += 1; expectedPublished += 1; assert.equal(a.seq, maxSeq); }
    } else if (r < 0.55) {
      const c = `c${Math.floor(rand() * 3)}`;
      bus.advance(c, Math.floor(rand() * (maxSeq + 1)) && bus.register(c) + Math.floor(rand() * (maxSeq + 1)));
      // advance may not move backwards; use register to read current then advance to random >= current
    } else if (r < 0.65) {
      await bus.truncate(Math.floor(rand() * (maxSeq + 2)));
    } else if (r < 0.72) {
      await bus.compact();
    } else if (r < 0.8) {
      const c = `c${Math.floor(rand() * 3)}`;
      bus.read(c);
    } else if (r < 0.9) {
      await bus.replay(Math.floor(rand() * (maxSeq + 2)));
    } else {
      await bus.close();
      bus = createBus({ path: dir, fsync: round % 2 === 0 });
    }
    if (step % 10 === 9) await check();
  }
  await check();
  await bus.close();
  // final reopen check
  bus = createBus({ path: dir });
  await check();
  // dedup survives everything
  for (const [key, ack] of firstAck) {
    assert.deepEqual(await bus.publish({ again: 1, dedupKey: key }), ack, `dedup lost for ${key}`);
  }
  await bus.close();
  rmSync(dir, { recursive: true, force: true });
}
